return [{
  json: {
    id: '1XvtzTLE-TAizIv9L6kmNKWACoqZiChLPNV4_I6Djj6A',
    name: 'Aanbevolen Artikelen',
    mimeType: 'application/vnd.google-apps.spreadsheet'
  }
}];

// Get data from Find Sheet node
const found = $('Find Sheet').all();
const first = found[0]?.json;

if (first?.id) {
  return [{ 
    json: { 
      spreadsheetId: first.id, 
      sheetName: "Aanbevolen Artikelen", 
      needsCreate: false 
    } 
  }];
}

return [{ 
  json: { 
    sheetName: "Aanbevolen Artikelen", 
    needsCreate: true 
  } 
}];

// Get the spreadsheet ID from the moved file
const data = $input.first().json;
const spreadsheetId = data.spreadsheetId || data.id;

return [{
  json: {
    spreadsheetId: spreadsheetId,
    sheetName: "Aanbevolen Artikelen"
  }
}];

const spreadsheetId = $input.first().json.spreadsheetId;
const sheetName = $input.first().json.sheetName;

// Try to read the sheet
try {
  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'GET',
      url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/${encodeURIComponent(sheetName)}!A:Z`,
      json: true
    }
  );

  const rows = response.values || [];
  const urls = rows.slice(1) // Skip header row
    .map(row => row[0]) // Assume URL is first column
    .filter(Boolean)
    .filter(u => typeof u === 'string')
    .map(u => u.trim())
    .filter(u => u && u.toLowerCase() !== 'url');

  return [{ json: { existingUrls: urls } }];
} catch (error) {
  // Sheet is empty or doesn't exist yet
  console.log('No existing data:', error.message);
  return [{ json: { existingUrls: [] } }];
}

const articles = [];
const inputItems = $input.all();

console.log('===== EXTRACTION START =====');
console.log('Input items:', inputItems.length);

for (let idx = 0; idx < inputItems.length; idx++) {
  const item = inputItems[idx];
  console.log(`\n=== Email ${idx + 1} ===`);

  const html = item.json.html || '';
  const emailDate = item.json.date ? new Date(item.json.date) : new Date();

  console.log('HTML length:', html.length);

  if (!html) {
    console.log('⚠️ No HTML');
    continue;
  }

  // Split by the unique class to find articles
  const segments = html.split('class="gse_alrt_title"');
  console.log('Found segments:', segments.length - 1);

  for (let i = 1; i < segments.length; i++) {
    try {
      // Get the part before the class (contains href)
      const before = segments[i - 1];
      // Get the part after the class (contains title and metadata)
      const after = segments[i];

      // Extract href from before (last href="...")
      const hrefMatch = before.match(/href="([^"]+)"[^>]*$/);
      if (!hrefMatch) continue;

      // Extract title from after (first >...</a>)
      const titleMatch = after.match(/^[^>]*>([^<]+)<\/a>/);
      if (!titleMatch) continue;

      const url = hrefMatch[1];
      const title = titleMatch[1];

      // Extract authors and source - next div with color:#006621
      let authors = '';
      let source = '';
      const authorsMatch = after.match(/<div[^>]*color:#006621[^>]*>([^<]+)<\/div>/);
      if (authorsMatch) {
        const authorSource = authorsMatch[1].trim();
        // Format: "Authors - Source, Year" or "Authors - Source"
        const parts = authorSource.split(' - ');
        if (parts.length >= 1) {
          authors = parts[0].trim();
        }
        if (parts.length >= 2) {
          source = parts[1].trim();
        }
      }

      // Extract summary - next div with class="gse_alrt_sni"
      let summary = '';
      const summaryMatch = after.match(/<div[^>]*class="gse_alrt_sni"[^>]*>([^<]+)/);
      if (summaryMatch) {
        summary = summaryMatch[1].trim().replace(/\s+/g, ' ');
      }

      console.log(`  ${i}. ${title.substring(0, 40)}...`);

      // Clean URL (extract real URL from scholar redirect)
      let cleanUrl = url;
      if (url.includes('scholar.google')) {
        const urlParam = url.match(/url=([^&]+)/);
        if (urlParam) {
          cleanUrl = decodeURIComponent(urlParam[1]);
        }
      }

      articles.push({
        title: title.trim(),
        url: cleanUrl.trim(),
        authors: authors,
        source: source,
        summary: summary,
        emailDate: emailDate.toISOString(),
        addedDate: new Date().toISOString()
      });
    } catch (err) {
      console.log(`  Error parsing article ${i}:`, err.message);
    }
  }

  console.log(`✓ Email ${idx + 1}: extracted ${segments.length - 1} articles`);
}

console.log(`\n===== TOTAL: ${articles.length} articles =====`);

return articles.map(article => ({ json: article }));

const items = $input.all();
if (!items.length) return [];

const firstItem = items[0].json;
const existingUrls = firstItem.existingUrls || [];
const spreadsheetId = firstItem.spreadsheetId;
const sheetName = firstItem.sheetName;

const existing = new Set(existingUrls.filter(u => u && typeof u === 'string').map(u => u.toLowerCase()));
const output = [];

for (const item of items) {
  const url = (item.json.url || item.json.URL || '').toString().trim();
  if (!url) continue;
  if (existing.has(url.toLowerCase())) continue;

  // Include all fields including metadata
  output.push({ 
    json: {
      url: item.json.url,
      title: item.json.title,
      authors: item.json.authors,
      source: item.json.source,
      summary: item.json.summary,
      emailDate: item.json.emailDate,
      addedDate: item.json.addedDate,
      spreadsheetId: spreadsheetId,
      sheetName: sheetName
    }
  });
}

return output;

const items = $input.all();
if (!items.length) return [];

const spreadsheetId = items[0].json.spreadsheetId;
const sheetName = items[0].json.sheetName;

// Build rows array
const rows = items.map(item => [
  item.json.url || '',
  item.json.title || '',
  item.json.authors || '',
  item.json.source || '',
  item.json.summary || '',
  item.json.emailDate || '',
  item.json.addedDate || ''
]);

return [{
  json: {
    spreadsheetId,
    sheetName,
    rows
  }
}];
